import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import net from 'node:net';
import { createHash, randomBytes } from 'node:crypto';
import { spawn } from 'node:child_process';
import { createInterface } from 'node:readline';
import { pathToFileURL, fileURLToPath } from 'node:url';
import { setTimeout as delay } from 'node:timers/promises';

const repo = 'D:/ClaudeProjects/ai_acknowladge';
const { runProcess, runDocker, cleanDockerEnvironment, verificationResources } = await import(pathToFileURL(path.join(repo, 'scripts/demo-verification-utils.mjs')));
const { verifyDemoProxyTimeouts } = await import(pathToFileURL(path.join(repo, 'scripts/verify-demo-proxy-timeouts.mjs')));
const env = cleanDockerEnvironment();
const runId = randomBytes(16).toString('hex');
const project = 'zhiliao-demo-clock-verify-' + runId.slice(0, 12);
const runLabel = 'io.zhiliao.demo-clock-verify.run';
const clockPath = '/sys/devices/system/clocksource/clocksource0/current_clocksource';
const target = 'tsc';
const evidenceDir = path.join(repo, 'docs/验收证据');
const evidencePath = path.join(evidenceDir, 'story-2-2-tick-maintenance-' + new Date().toISOString().replace(/[:.]/g, '-') + '.json');
const relative = (file) => path.relative(repo, file).replaceAll('\\', '/');
const hash = (file) => createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const invoke = (args, timeoutMs = 15000) => runDocker(args, { env, timeoutMs });
const wsl = (args, input) => runProcess('wsl.exe', ['-d', 'docker-desktop', '-u', 'root', '--', ...args], { env, input, timeoutMs: 15000 });
const readClock = () => wsl(['cat', clockPath]);
const diagnosisFile = path.join(evidenceDir, 'story-2-2-clock-diagnostics-2026-09-12T04-59-16-594Z.json');
const diagnosis = JSON.parse(fs.readFileSync(diagnosisFile, 'utf8'));
if (createHash('sha256').update(diagnosis.python_probe).digest('hex') !== diagnosis.python_probe_sha256) throw new Error('只读探针存证哈希不匹配');
const pythonPrefix = diagnosis.python_probe.split('for incoming in sys.stdin:')[0];
if (pythonPrefix === diagnosis.python_probe) throw new Error('只读探针前缀不匹配');
const timexSource = pythonPrefix + `
buf = ctypes.create_string_buffer(1024)
mode = sys.argv[1]
if mode == 'set':
    requested = int(sys.argv[2])
    assert os.sysconf('SC_CLK_TCK') == 100 and 9000 <= requested <= 11000
    request = TimexPrefix.from_buffer(buf)
    request.modes = 0x4000
    request.tick = requested
else:
    assert mode == 'read'
result = libc.adjtimex(ctypes.byref(buf))
error = ctypes.get_errno()
value = TimexPrefix.from_buffer_copy(buf.raw)
print(json.dumps({'result': result, 'errno': error, 'modes_input': 0x4000 if mode == 'set' else 0,
                 'tick_us': value.tick, 'freq_scaled_ppm': value.freq, 'freq_ppm': value.freq / 65536,
                 'status': value.status, 'user_hz': os.sysconf('SC_CLK_TCK')}))
`;
async function timex(mode, value) {
  if (!['read', 'set'].includes(mode) || (mode === 'set' && (!Number.isInteger(value) || value < 9000 || value > 11000))) throw new Error('拒绝范围外调时参数');
  const args = ['-d', 'Ubuntu-24.04', '-u', 'root', '--', 'python3', '-c', timexSource, mode];
  if (mode === 'set') args.push(String(value));
  const result = JSON.parse(await runProcess('wsl.exe', args, { env, timeoutMs: 15000 }));
  if (result.result < 0 || result.user_hz !== 100) throw new Error('adjtimex 调用失败：' + JSON.stringify(result));
  return result;
}
if (process.argv.includes('--read-only')) {
  console.log(JSON.stringify({ scope: '仅核对 Python ABI 与只读模式', clocksource: await readClock(), timex: await timex('read') }));
  process.exit(0);
}
const resources = verificationResources(invoke, project, runId, runLabel);
const progress = (event) => console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
const containerFormat = '{"id":{{json .Id}},"name":{{json .Name}},"image":{{json .Image}},"status":{{json .State.Status}},"exit_code":{{json .State.ExitCode}},"started_at":{{json .State.StartedAt}},"finished_at":{{json .State.FinishedAt}},"project":{{json (index .Config.Labels "com.docker.compose.project")}},"mounts":{{json .Mounts}},"networks":{{json .NetworkSettings.Networks}}}';
async function containers() {
  const ids = (await invoke(['ps', '-a', '--no-trunc', '--format', '{{.ID}}'])).split(/\r?\n/).filter(Boolean);
  if (!ids.length) return [];
  return (await invoke(['container', 'inspect', '--format', containerFormat, ...ids])).split(/\r?\n/).filter(Boolean).map((line) => {
    const item = JSON.parse(line);
    item.mounts.sort((a, b) => a.Destination.localeCompare(b.Destination));
    item.networks = Object.keys(item.networks ?? {}).sort();
    return item;
  }).sort((a, b) => a.id.localeCompare(b.id));
}
const report = {
  story: '2.2', recorded_at: new Date().toISOString(), status: 'failed', run_id: runId, project,
  scope: '用户获知单独校正 tick 与恢复范围后要求继续；临时设置 ADJ_TICK=10000，计时通过后复验 A2，最终恢复起始 tick',
  authorization: '仅临时写 ADJ_TICK 与条件复验；不修改 freq、NTP 状态、系统时间或时钟源，不重启、构建、运行全量测试或发布',
  host: { platform: process.platform, release: os.release(), node: process.version },
  source_file: path.basename(fileURLToPath(import.meta.url)), source_sha256: hash(fileURLToPath(import.meta.url)),
  maintenance_source: fs.readFileSync(fileURLToPath(import.meta.url), 'utf8'),
  clock: { path: clockPath, required: target, changed: false },
  tick: { requested: 10000, correction_attempted: false, restore: { status: 'not_needed' }, monitor: [] },
  timex_source: timexSource, diagnosis_input_sha256: hash(diagnosisFile),
  timing: { interval_ms: 20000, maximum_relative_error: 0.01, status: 'not_run', samples: [], intervals: [] },
  proxy: { status: 'not_run', reason: '必须先通过计时门槛' },
  cleanup: { status: 'not_started' }, limitations: [
    '本次仅临时校正 tick；恢复起始值后不能推断原环境长期计时已修复，也不证明持续调参组件已定位。',
    '不替代最终主机隔离、业务卷配额、HTTPS 与补丁镜像发布验收。'
  ]
};
let beforeContainers;
let protectedFiles;
let probe;
let closeProbe;
let proxyCompose;
let proxyOwner;
let monitor;
let monitorPending = Promise.resolve();
let proxyStarted = false;
const probeSource = diagnosis.python_probe;
report.timing.guest_probe = probeSource;
async function stopProxy() {
  if (!proxyCompose || !proxyOwner) throw new Error('缺少可核对的本次代理资源');
  const owned = verificationResources(invoke, proxyOwner.project, proxyOwner.runId, 'io.zhiliao.demo-proxy-verify.run');
  const items = await owned.list();
  await owned.assertOwned(items);
  const ids = items.filter((item) => item.type === 'container').map((item) => item.id);
  if (ids.length) await invoke(['container', 'stop', '--time', '1', ...ids], 20000);
  report.tick.proxy_stopped = true;
}
async function monitorTick() {
  if (!proxyStarted || report.tick.interference) return;
  try {
    const value = await timex('read');
    const predicted = value.tick_us / 10000 + value.freq_ppm / 1e6;
    report.tick.monitor.push({ at: new Date().toISOString(), ...value, predicted_rate: predicted });
    if (Math.abs(predicted - 1) > 0.01 || await readClock() !== 'tsc') {
      report.tick.interference = '代理复验期间计时参数再次超出 1% 范围或时钟源变化';
      progress({ stage: 'tick_interference', ...value });
      await stopProxy();
    }
  } catch (error) {
    report.tick.interference ??= String(error.message ?? error);
    try { await stopProxy(); } catch (stopError) { report.tick.stop_error = String(stopError.message ?? stopError); }
  }
}
try {
  if (fs.existsSync(evidencePath)) throw new Error('证据路径已经存在');
  report.baseline_commit = await runProcess('git', ['rev-parse', 'HEAD'], { env });
  beforeContainers = await containers();
  if (beforeContainers.some((item) => item.status === 'running')) throw new Error('发现运行中的既有容器，停止本次计时维护');
  const prior = JSON.parse(fs.readFileSync(path.join(evidenceDir, 'story-2-2-preservation-2026-09-12-a2.json'), 'utf8'));
  const keep = new Set(prior.protected_files.map((item) => item.path));
  for (const file of fs.readdirSync(evidenceDir).filter((item) => item.endsWith('.json'))) keep.add('docs/验收证据/' + file);
  for (const file of ['README.md', 'README.en.md', '.dockerignore', '.gitignore', 'docs/README.md', 'docs/首次使用与故障排查.md', 'docs/Demo部署隔离验收-2026-09-10.md', 'docs/Story-2.2-剩余验收实施方案-2026-09-11.md', 'docs/adr/0026-demo-ingress-isolation.md', '_bmad-output/implementation-artifacts/spec-2-2-isolate-demo-deployment-and-limit-resources.md', '_bmad-output/implementation-artifacts/sprint-status.yaml', 'scripts/demo-verification-utils.mjs', 'scripts/verify-demo-network.mjs', 'scripts/verify-demo-proxy-timeouts.mjs', 'scripts/fixtures/demo-proxy-upstream.mjs', 'nginx/demo-proxy.conf', 'docker-compose.demo.proxy-verify.yml', 'tests/config/demo-network.test.ts', 'tests/config/demo-proxy-timeouts.test.ts', 'tests/docs/first-use-guide.test.ts']) keep.add(file);
  protectedFiles = [...keep].sort().map((file) => ({ path: file, sha256_before: hash(path.join(repo, file)) }));
  report.clock.original = await readClock();
  report.clock.available = (await wsl(['cat', '/sys/devices/system/clocksource/clocksource0/available_clocksource'])).split(/\s+/);
  report.kernel = await wsl(['uname', '-r']);
  if (report.clock.original !== 'tsc' || !report.clock.available.includes(target)) throw new Error('时钟源前提已变化，停止维护');
  report.candidate_image_id = await invoke(['image', 'inspect', '--format', '{{.Id}}', 'zhiliao-demo-verify:story-2-2']);
  if (report.candidate_image_id !== 'sha256:46f9241b6d2e539ce3a94324c356cf4336f8cf17e0cf59e5b5d920bf9b53769e') throw new Error('候选镜像与 A2 历史来源不一致');
  const imageVolumes = JSON.parse(await invoke(['image', 'inspect', '--format', '{{json .Config.Volumes}}', report.candidate_image_id]));
  if (imageVolumes && Object.keys(imageVolumes).length) throw new Error('候选含镜像卷声明，拒绝启动计时探针');
  report.nginx_image_id = await invoke(['image', 'inspect', '--format', '{{.Id}}', 'nginx:1.30.4-alpine@sha256:dc5069ad14f19660b141b21236140b91656bf89bbc3e2417c70ae650cd66104c']);
  await new Promise((resolve, reject) => {
    const server = net.createServer();
    server.once('error', reject);
    server.listen(3333, '127.0.0.1', () => server.close((error) => error ? reject(error) : resolve()));
  });
  if ((await resources.list()).length) throw new Error('计时探针 project 已存在资源');
  report.probe_boundary = { implementation: 'WSL 已有 Python 读取共用内核；无容器、网络、挂载或文件写入', timex_modes: 0 };
  probe = spawn('wsl.exe', ['-d', 'Ubuntu-24.04', '-u', 'root', '--', 'python3', '-u', '-c', probeSource], { cwd: repo, env, windowsHide: true, stdio: 'pipe' });
  const pending = new Map();
  let sequence = 0;
  let probeFailure;
  const failPending = (error) => { probeFailure = error; for (const { reject } of pending.values()) reject(error); pending.clear(); };
  const closed = new Promise((resolve) => probe.once('close', (code) => { failPending(new Error('计时探针已退出：' + code)); resolve(code); }));
  probe.on('error', failPending);
  probe.stdin.on('error', failPending);
  probe.stderr.resume();
  const lines = createInterface({ input: probe.stdout, crlfDelay: Infinity });
  lines.on('line', (line) => {
    const hostAfter = { wall_ms: Date.now(), monotonic_ms: performance.now() };
    try {
      const guest = JSON.parse(line);
      const request = pending.get(guest.id);
      if (!request) return;
      pending.delete(guest.id);
      request.resolve({ host_before: request.before, host_after: hostAfter, round_trip_ms: hostAfter.monotonic_ms - request.before.monotonic_ms, guest });
    } catch (error) { failPending(error); }
  });
  const sample = () => new Promise((resolve, reject) => {
    if (probeFailure) { reject(probeFailure); return; }
    const id = String(++sequence);
    const timer = setTimeout(() => { pending.delete(id); reject(new Error('计时探针采样超时')); }, 10000);
    pending.set(id, { before: { wall_ms: Date.now(), monotonic_ms: performance.now() }, resolve: (value) => { clearTimeout(timer); resolve(value); }, reject: (error) => { clearTimeout(timer); reject(error); } });
    probe.stdin.write(id + '\n');
  });
  closeProbe = async () => {
    probe.stdin.end();
    let timer;
    const code = await Promise.race([closed, new Promise((resolve) => { timer = setTimeout(() => { probe.kill(); resolve('timeout'); }, 5000); })]);
    clearTimeout(timer);
    lines.close();
    report.probe_exit_code = code;
    if (code !== 0) throw new Error('计时采样进程结束异常：' + code);
  };
  report.timing.warmup = await sample();
  report.tick.original = await timex('read');
  if (!Number.isInteger(report.tick.original.tick_us) || report.tick.original.tick_us < 9000 || report.tick.original.tick_us > 11000) throw new Error('起始 tick 超出已审查范围');
  if (report.tick.original.tick_us !== 10000) {
    report.tick.correction_attempted = true;
    report.tick.corrected_at = new Date().toISOString();
    report.tick.write_result = await timex('set', 10000);
  }
  report.tick.after_correction = await timex('read');
  if (report.tick.after_correction.tick_us !== 10000 || await readClock() !== 'tsc') throw new Error('tick 校正后读回不匹配或时钟源变化');
  progress({ stage: 'tick_corrected', original: report.tick.original.tick_us, current: report.tick.after_correction.tick_us });
  const bestSample = async () => {
    const candidates = [];
    for (let i = 0; i < 3; i++) candidates.push(await sample());
    report.timing.samples.push(...candidates);
    if (candidates.some((item) => item.guest.clocksource !== target)) throw new Error('采样期间时钟源发生变化');
    return candidates.reduce((best, item) => item.round_trip_ms < best.round_trip_ms ? item : best);
  };
  let previous = await bestSample();
  for (let i = 0; i < 2; i++) {
    await delay(20000);
    const next = await bestSample();
    const hostMin = next.host_before.monotonic_ms - previous.host_after.monotonic_ms;
    const hostMax = next.host_after.monotonic_ms - previous.host_before.monotonic_ms;
    const guestMs = Number(BigInt(next.guest.monotonic_ns) - BigInt(previous.guest.monotonic_ns)) / 1e6;
    const rawMs = Number(BigInt(next.guest.raw_ns) - BigInt(previous.guest.raw_ns)) / 1e6;
    const lower = guestMs / hostMax;
    const upper = guestMs / hostMin;
    const worstError = Math.max(Math.abs(lower - 1), Math.abs(upper - 1));
    const rawError = Math.max(Math.abs(rawMs / hostMax - 1), Math.abs(rawMs / hostMin - 1));
    const interval = { sample_ids: [previous.guest.id, next.guest.id], host_min_ms: hostMin, host_max_ms: hostMax, guest_ms: guestMs, guest_raw_ms: rawMs, guest_to_host_ratio_min: lower, guest_to_host_ratio_max: upper, maximum_relative_error: worstError, raw_maximum_relative_error: rawError, tick: next.guest.timex, passed: hostMin > 0 && worstError <= 0.01 && rawError <= 0.01 };
    report.timing.intervals.push(interval);
    progress({ stage: 'clock_interval', interval: i + 1, ...interval });
    previous = next;
  }
  report.timing.status = report.timing.intervals.every((item) => item.passed) ? 'passed' : 'failed';
  await closeProbe();
  closeProbe = undefined;
  if (report.timing.status !== 'passed') throw new Error('计时差不能确认不超过 1%，按方案停止长时复验');
  progress({ stage: 'proxy_reverification_started', clocksource: await readClock() });
  monitor = setInterval(() => { monitorPending = monitorPending.then(monitorTick); }, 10000);
  const verified = await verifyDemoProxyTimeouts({ port: 3333 }, {
    docker: async (args, options) => {
      const up = args.indexOf('up');
      if (args[0] === 'compose' && up >= 0) {
        proxyCompose = args.slice(0, up);
        const proxyProject = args[args.indexOf('-p') + 1];
        const envFile = args[args.indexOf('--env-file') + 1];
        const id = /^DEMO_VERIFY_RUN_ID=([a-f0-9]{32})$/m.exec(fs.readFileSync(envFile, 'utf8'))?.[1];
        if (!/^zhiliao-demo-proxy-verify-[a-f0-9]+$/.test(proxyProject) || !id) throw new Error('无法核对代理监测所需归属');
