  if (report.tick.interference || Math.abs(report.tick.after_proxy.tick_us / 10000 + report.tick.after_proxy.freq_ppm / 1e6 - 1) > 0.01) throw new Error(report.tick.interference ?? '代理复验结束时 tick 再次异常');
  if (verified.exitCode !== 0) throw new Error('代理复验或资源清理仍有未通过项');
  report.status = 'passed';
} catch (error) {
  report.error = String(error.message ?? error);
  progress({ stage: 'failed', error: report.error });
} finally {
