        report.clock.after_restore = await readClock();
        if (report.clock.after_restore !== 'tsc') throw new Error('时钟源发生外部变化');
        progress({ stage: 'tick_restored', tick_us: report.tick.restore.after.tick_us, clocksource: report.clock.after_restore });
      } catch (error) { report.tick.restore.status = 'failed'; report.tick.restore.error = String(error.message ?? error); report.status = 'failed'; }
    }
